import type { SkeletonProps } from "./skeleton.types";
import type { ComponentStyleVariantConfig, Theme } from "@types";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "Skeleton";

// Generate child element class names for the component, should match available style slots
export const SkeletonClasses = {
  root: "exp-textura_skeleton",
  square: "exp-textura_skeleton_square",
  round: "exp-textura_skeleton_round",
  xsm: "exp-textura_skeleton_xsm",
  sm: "exp-textura_skeleton_sm",
  md: "exp-textura_skeleton_md",
  lg: "exp-textura_skeleton_lg",
  xlg: "exp-textura_skeleton_xlg",
  xxlg: "exp-textura_skeleton_xxlg",
};

// Set up style variant settings for the component (if more than "default"), using style slots
const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
  inverse: {
    square: {
      backgroundColor: theme.progressSkeleton.inverse.square.color.background,
      borderRadius: theme.toRem(theme.progressSkeleton.inverse.square.border.radius),
    },
    round: {
      backgroundColor: theme.progressSkeleton.inverse.round.color.background,
      borderRadius: theme.toRem(theme.progressSkeleton.inverse.round.border.radius),
    },
  },
});

const generateStyles = (props: SkeletonProps) => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<SkeletonProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    display: "inline-block",
    animation: "exp-textura_skeleton 0.75s infinite alternate-reverse",
    pointerEvents: "none",
    userSelect: "none",
    color: "transparent",
    outline: "none",
    height: "fit-content",
    width: "fit-content",

    [`> [aria-hidden="true"]`]: {
      visibility: "hidden",
      ...styleSlots?.hiddenChild,
    },

    // size styles
    [`&.${SkeletonClasses.xsm}`]: {
      height: theme.toRem(12),
      width: theme.toRem(12),
      ...styleSlots?.xsm,
    },
    [`&.${SkeletonClasses.sm}`]: {
      height: theme.toRem(20),
      width: theme.toRem(20),
      ...styleSlots?.sm,
    },
    [`&.${SkeletonClasses.md}`]: {
      height: theme.toRem(28),
      width: theme.toRem(28),
      ...styleSlots?.md,
    },
    [`&.${SkeletonClasses.lg}`]: {
      height: theme.toRem(36),
      width: theme.toRem(36),
      ...styleSlots?.lg,
    },
    [`&.${SkeletonClasses.xlg}`]: {
      height: theme.toRem(44),
      width: theme.toRem(44),
      ...styleSlots?.xlg,
    },
    [`&.${SkeletonClasses.xxlg}`]: {
      height: theme.toRem(56),
      width: theme.toRem(56),
      ...styleSlots?.xxlg,
    },

    // shape styles
    [`&.${SkeletonClasses.round}`]: {
      borderRadius: theme.toRem(theme.progressSkeleton.default.round.border.radius),
      backgroundColor: theme.progressSkeleton.default.round.color.background,
      ...styleSlots?.round,
    },
    [`&.${SkeletonClasses.square}`]: {
      borderRadius: theme.toRem(theme.progressSkeleton.default.square.border.radius),
      backgroundColor: theme.progressSkeleton.default.square.color.background,
      width: "100%",
      ...styleSlots?.square,
    },

    "@keyframes exp-textura_skeleton": {
      from: {
        opacity: 0.45,
      },
      to: {
        opacity: 0.8,
      },
    },
    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledSkeleton = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<SkeletonProps>((props) => generateStyles(props));
